public class FeedFanoutService
{
    private readonly IDatabase _redis;

    public async Task PublishPostAsync(Post post)
    {
        var author = _users[post.AuthorId];
        foreach (var followerId in author.Following)
        {
            var key = $"feed:{followerId}";
            await _redis.ListRightPushAsync(key, JsonSerializer.Serialize(post));
            await _redis.ListTrimAsync(key, 0, 999); // keep last 1000 posts
        }
    }

    public async Task<IEnumerable<Post>> GetFeedAsync(Guid userId, int page, int pageSize)
    {
        var key = $"feed:{userId}";
        var start = (page - 1) * pageSize;
        var posts = await _redis.ListRangeAsync(key, start, start + pageSize - 1);
        return posts.Select(p => JsonSerializer.Deserialize<Post>(p)!);
    }
}
